#include <stdio.h>
#include <stdatomic.h>

static atomic_int count;

static int is_prime(int n)
{
    if (n < 2) return 0;
    for (int d = 2; d * d <= n; d++)
        if (n % d == 0) return 0;
    return 1;
}

int main(void)
{
    atomic_store(&count, 0);
    printf("primes: %d\n", atomic_load(&count));
    return 0;
}
